class ExchangeClient(Protocol):
    id: str

    def load_markets(
        self,
    ) -> Mapping[str, Mapping[str, object]]:
        ...

    def fetch_ohlcv(
        self,
        symbol: str,
        timeframe: str,
        since: int | None = None,
        limit: int | None = None,
    ) -> list[list[OHLCVValue]]:
        ...

class HistoryResult:
    exchange_id: str
    symbol: str
    timeframe: str
    since: datetime
    until: datetime
    pages: int
    frame: pd.DataFrame

    @property
    def rows(self) -> int:
        return len(self.frame)

def _open_timestamp_ms(row: OHLCVRow) -> int:
    if len(row) < 6:
        raise DataIntegrityError(
            "OHLCV row must contain at least six values."
        )

    value = row[0]

    if isinstance(value, bool) or not isinstance(
        value,
        (int, float),
    ):
        raise DataIntegrityError(
            "OHLCV timestamp must be numeric."
        )

    timestamp = float(value)

    if not math.isfinite(timestamp):
        raise DataIntegrityError(
            "OHLCV timestamp must be finite."
        )

    return int(timestamp)

def normalize_ohlcv_rows(
    rows: Sequence[OHLCVRow],
    *,
    timeframe: str,
    since: datetime,
    until: datetime,
) -> pd.DataFrame:
    since_utc = _require_aware_utc(
        since,
        name="since",
    )
    until_utc = _require_aware_utc(
        until,
        name="until",
    )

    if until_utc <= since_utc:
        raise ValueError(
            "until must be later than since."
        )

    duration_ms = timeframe_to_milliseconds(timeframe)
    since_ms = _datetime_to_milliseconds(since_utc)
    until_ms = _datetime_to_milliseconds(until_utc)

    records: list[dict[str, object]] = []

    for row in rows:
        open_ms = _open_timestamp_ms(row)
        close_ms = open_ms + duration_ms

        if open_ms < since_ms:
            continue

        if open_ms >= until_ms:
            continue

        # The candle is incomplete at the requested as-of time.
        if close_ms > until_ms:
            continue

        records.append(
            {
                "timestamp": pd.Timestamp(
                    close_ms,
                    unit="ms",
                    tz="UTC",
                ),
                "open": _finite_float(
                    row[1],
                    field="open",
                ),
                "high": _finite_float(
                    row[2],
                    field="high",
                ),
                "low": _finite_float(
                    row[3],
                    field="low",
                ),
                "close": _finite_float(
                    row[4],
                    field="close",
                ),
                "volume": _finite_float(
                    row[5],
                    field="volume",
                ),
            }
        )

    frame = pd.DataFrame.from_records(
        records,
        columns=list(REQUIRED_COLUMNS),
    )

    if frame.empty:
        return frame

    frame["timestamp"] = pd.to_datetime(
        frame["timestamp"],
        utc=True,
    )

    return frame.sort_values(
        by="timestamp",
        kind="stable",
    ).reset_index(drop=True)

class CCXTSpotDataProvider:
    def __init__(
        self,
        exchange: ExchangeClient,
        *,
        max_pages: int = 10_000,
    ) -> None:
        if max_pages < 1:
            raise ValueError(
                "max_pages must be at least 1."
            )

        self.exchange = exchange
        self.max_pages = max_pages

    def _validate_spot_market(
        self,
        symbol: str,
    ) -> None:
        markets = self.exchange.load_markets()
        market = markets.get(symbol)

        if market is None:
            raise MarketValidationError(
                f"Market not found: {symbol}"
            )

        if market.get("spot") is not True:
            raise MarketValidationError(
                f"Market is not explicitly Spot: {symbol}"
            )

        forbidden_flags = (
            "contract",
            "swap",
            "future",
            "option",
        )

        for flag in forbidden_flags:
            if market.get(flag) is True:
                raise MarketValidationError(
                    f"Forbidden market flag {flag!r} "
                    f"detected for {symbol}."
                )

        if market.get("active") is False:
            raise MarketValidationError(
                f"Market is inactive: {symbol}"
            )

    def fetch_history(
        self,
        *,
        symbol: str,
        timeframe: str,
        since: datetime,
        until: datetime,
        page_limit: int = 1_000,
    ) -> HistoryResult:
        if not symbol.strip():
            raise ValueError(
                "Symbol cannot be empty."
            )

        if page_limit < 1 or page_limit > 1_000:
            raise ValueError(
                "page_limit must be between 1 and 1000."
            )

        since_utc = _require_aware_utc(
            since,
            name="since",
        )
        until_utc = _require_aware_utc(
            until,
            name="until",
        )

        if until_utc <= since_utc:
            raise ValueError(
                "until must be later than since."
            )

        self._validate_spot_market(symbol)

        duration_ms = timeframe_to_milliseconds(timeframe)
        cursor_ms = _datetime_to_milliseconds(since_utc)
        until_ms = _datetime_to_milliseconds(until_utc)

        raw_rows: list[OHLCVRow] = []
        pages = 0

        while cursor_ms < until_ms:
            if pages >= self.max_pages:
                raise PaginationError(
                    "Maximum pagination limit exceeded."
                )

            page = self.exchange.fetch_ohlcv(
                symbol,
                timeframe,
                since=cursor_ms,
                limit=page_limit,
            )
            pages += 1

            if not page:
                break

            raw_rows.extend(page)

            maximum_open_ms = max(
                _open_timestamp_ms(row)
                for row in page
            )

            next_cursor_ms = (
                maximum_open_ms + duration_ms
            )

            if next_cursor_ms <= cursor_ms:
                raise PaginationError(
                    "Exchange pagination did not advance."
                )

            cursor_ms = next_cursor_ms

        frame = normalize_ohlcv_rows(
            raw_rows,
            timeframe=timeframe,
            since=since_utc,
            until=until_utc,
        )

        if frame.empty:
            raise DataIntegrityError(
                f"No complete candles returned for "
                f"{symbol} {timeframe}."
            )

        report = validate_candles(
            frame,
            symbol=symbol,
            expected_frequency=timeframe,
        )

        if not report.is_valid:
            raise DataIntegrityError(
                "Historical data validation failed: "
                f"rows={report.rows}, "
                f"duplicates={report.duplicate_timestamps}, "
                f"missing={report.missing_intervals}, "
                f"invalid={report.invalid_rows}"
            )

        return HistoryResult(
            exchange_id=self.exchange.id,
            symbol=symbol,
            timeframe=timeframe,
            since=since_utc,
            until=until_utc,
            pages=pages,
            frame=frame,
        )

class ParquetCandleStore:
    def __init__(self, root: Path) -> None:
        self.root = root

    def dataset_path(
        self,
        *,
        exchange_id: str,
        symbol: str,
        timeframe: str,
    ) -> Path:
        timeframe_to_timedelta(timeframe)

        exchange_component = _safe_component(
            exchange_id
        )
        symbol_component = _safe_component(
            symbol.replace("/", "-").replace(":", "-")
        )
        timeframe_component = _safe_component(
            timeframe
        )

        return (
            self.root
            / exchange_component
            / symbol_component
            / f"{timeframe_component}.parquet"
        )

    @staticmethod
    def metadata_path(data_path: Path) -> Path:
        return data_path.with_suffix(
            ".metadata.json"
        )

    def save(
        self,
        frame: pd.DataFrame,
        *,
        exchange_id: str,
        symbol: str,
        timeframe: str,
        overwrite: bool = False,
    ) -> StoredDataset:
        report = validate_candles(
            frame,
            symbol=symbol,
            expected_frequency=timeframe,
        )

        if not report.is_valid:
            raise StorageIntegrityError(
                "Refusing to store invalid candle data."
            )

        data_path = self.dataset_path(
            exchange_id=exchange_id,
            symbol=symbol,
            timeframe=timeframe,
        )
        metadata_path = self.metadata_path(
            data_path
        )

        if data_path.exists() and not overwrite:
            raise FileExistsError(
                f"Dataset already exists: {data_path}"
            )

        data_path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

        normalized = frame.loc[
            :,
            list(REQUIRED_COLUMNS),
        ].copy()

        normalized["timestamp"] = pd.to_datetime(
            normalized["timestamp"],
            utc=True,
        )

        normalized = normalized.sort_values(
            by="timestamp",
            kind="stable",
        ).reset_index(drop=True)

        timestamp_values = cast(
            list[pd.Timestamp],
            normalized["timestamp"].tolist(),
        )

        temporary_data_path = data_path.with_name(
            f".{data_path.name}.{uuid4().hex}.tmp"
        )

        temporary_metadata_path = metadata_path.with_name(
            f".{metadata_path.name}.{uuid4().hex}.tmp"
        )

        try:
            normalized.to_parquet(
                temporary_data_path,
                index=False,
                engine="pyarrow",
            )

            digest = _sha256(
                temporary_data_path
            )

            metadata: dict[str, object] = {
                "schema_version": (
                    "spotbot-candles-v1"
                ),
                "exchange_id": exchange_id,
                "symbol": symbol,
                "timeframe": timeframe,
                "rows": len(normalized),
                "first_timestamp": (
                    timestamp_values[0].isoformat()
                ),
                "last_timestamp": (
                    timestamp_values[-1].isoformat()
                ),
                "sha256": digest,
            }

            temporary_metadata_path.write_text(
                json.dumps(
                    metadata,
                    ensure_ascii=False,
                    indent=2,
                    sort_keys=True,
                ),
                encoding="utf-8",
            )

            os.replace(
                temporary_data_path,
                data_path,
            )
            os.replace(
                temporary_metadata_path,
                metadata_path,
            )

        finally:
            temporary_data_path.unlink(
                missing_ok=True
            )
            temporary_metadata_path.unlink(
                missing_ok=True
            )

        return StoredDataset(
            data_path=data_path,
            metadata_path=metadata_path,
            rows=len(normalized),
            sha256=digest,
        )

    def load(
        self,
        *,
        exchange_id: str,
        symbol: str,
        timeframe: str,
        verify_integrity: bool = True,
    ) -> pd.DataFrame:
        data_path = self.dataset_path(
            exchange_id=exchange_id,
            symbol=symbol,
            timeframe=timeframe,
        )
        metadata_path = self.metadata_path(
            data_path
        )

        if not data_path.exists():
            raise FileNotFoundError(data_path)

        if not metadata_path.exists():
            raise StorageIntegrityError(
                f"Missing metadata file: {metadata_path}"
            )

        if verify_integrity:
            parsed: object = json.loads(
                metadata_path.read_text(
                    encoding="utf-8"
                )
            )

            if not isinstance(parsed, dict):
                raise StorageIntegrityError(
                    "Metadata must be a JSON object."
                )

            metadata = cast(
                dict[str, object],
                parsed,
            )
            expected_hash = metadata.get(
                "sha256"
            )

            if not isinstance(
                expected_hash,
                str,
            ):
                raise StorageIntegrityError(
                    "Metadata SHA-256 is missing."
                )

            actual_hash = _sha256(data_path)

            if actual_hash != expected_hash:
                raise StorageIntegrityError(
                    "Parquet checksum mismatch."
                )

        frame = pd.read_parquet(
            str(data_path)
        )

        report = validate_candles(
            frame,
            symbol=symbol,
            expected_frequency=timeframe,
        )

        if not report.is_valid:
            raise StorageIntegrityError(
                "Stored candle data failed validation."
            )

        return frame

def _timestamp(value: object) -> pd.Timestamp:
    result = pd.Timestamp(cast(Any, value))
    if result.tzinfo is None:
        return result.tz_localize("UTC")
    return result.tz_convert("UTC")

def _discover_first_open(
    adapter: CCXTExchangeAdapter,
    *,
    symbol: str,
    since: datetime,
    until: datetime,
) -> datetime:
    probe = since
    step = timedelta(days=90)
    while probe < until:
        rows = adapter.fetch_ohlcv(
            symbol,
            SIGNAL_TIMEFRAME,
            since=int(probe.timestamp() * 1_000),
            limit=1,
        )
        if rows:
            raw = rows[0][0]
            if isinstance(raw, bool) or not isinstance(
                raw,
                (int, float),
            ):
                raise RD16BDataError(f"Invalid listing timestamp: {symbol}")
            result = datetime.fromtimestamp(
                float(raw) / 1_000,
                tz=UTC,
            )
            if result >= until:
                raise RD16BDataError(f"No pre-cutoff candles found: {symbol}")
            return max(result, since)
        probe += step
    raise RD16BDataError(f"No hourly history found before cutoff: {symbol}")

def _frame_digest(frame: pd.DataFrame) -> str:
    normalized = frame.loc[
        :,
        list(REQUIRED_COLUMNS),
    ].copy()
    normalized["timestamp"] = pd.to_datetime(
        normalized["timestamp"],
        utc=True,
        errors="raise",
    ).map(lambda value: cast(pd.Timestamp, value).isoformat())
    payload = normalized.to_csv(
        index=False,
        lineterminator="\n",
        float_format="%.17g",
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()
